True def transform(grid):
    h, w = len(grid), len(grid[0])
    tile = [[0 if grid[r][c] else 1 for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                for tr in range(h):
                    for tc in range(w):
                        if tile[tr][tc]:
                            out[3 * r + tr][3 * c + tc] = color
    return out
